        int u, v, w;
        cin >> u >> v >> w;
        edges[i] = make_tuple(u, v, w);
    }

    for (int i = 0; i < q; ++i) {
        int l, r;
        cin >> l >> r;

        vector<tuple<int, int, int>> remaining_edges;
        for (int j = 0; j < m; ++j) {
            if (j + 1 >= l && j + 1 <= r) {
                remaining_edges.push_back(edges[j]);
            }
        }

        int min_hardness = -1;
        for (int j = 0; j < (1 << n); ++j) {
            vector<int> group1;
            vector<int> group2;
            for (int k = 0; k < n; ++k) {
                if ((j >> k) & 1) {
                    group1.push_back(k + 1);
                } else {
                    group2.push_back(k + 1);
                }
            }

            int max_hardness = -1;
            for (const auto& edge : remaining_edges) {
                int u = get<0>(edge);
                int v = get<1>(edge);
                int w = get<2>(edge);

                bool u_in_group1 = false;
                for (int node : group1) {
                    if (node == u) {
                        u_in_group1 = true;
