                bool v_in_group1 = false;
                for (int node : group1) {
                    if (node == v) {
                        v_in_group1 = true;
                        break;
                    }
                }

                if (u_in_group1 == v_in_group1) {
                    max_hardness = max(max_hardness, w);
                }
            }

