bool isZigzag(int n) {
    if (n < 10) {
        return true;
    }
    string s = to_string(n);
    bool increasing = s[1] > s[0];
    for (size_t i = 1; i < s.length() - 1; ++i) {
        if (increasing) {
            if (s[i + 1] >= s[i]) {
                return false;
            }
        } else {
            if (s[i + 1] <= s[i]) {
                return false;
            }
        }
        increasing = !increasing;
    }
    return true;
}

