using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> parent(n + 1, 0);
    for (int i = 2; i <= n; ++i) {
        cin >> parent[i];
    }

    vector<vector<int>> adj(n + 1);
    for (int i = 2; i <= n; ++i) {
        adj[parent[i]].push_back(i);
    }

    vector<bool> is_leaf(n + 1, true);
    for (int i = 1; i <= n; ++i) {
        if (!adj[i].empty()) {
            is_leaf[i] = false;
        }
    }

    vector<int> leaves;
    for (int i = 1; i <= n; ++i) {
        if (is_leaf[i]) {
            leaves.push_back(i);
        }
    }

    int max_leaves = 0;
    vector<bool> visited(n + 1, false);

    function<void(int, vector<bool>)> dfs = 
        [&](int current_node, vector<bool> current_visited) {

        current_visited[current_node] = true;

        int leaves_visited = 0;
        for (int leaf : leaves) {
            if (current_visited[leaf]) {
                leaves_visited++;
            }
        }
        max_leaves = max(max_leaves, leaves_visited);



        if (is_leaf[current_node]) {

            int current_depth = 0;
            int temp = current_node;
            while (temp != 1) {
                current_depth++;
                temp = parent[temp];
            }

            for (int i = 0; i <= k; ++i) {
                int ancestor = current_node;
                for (int j = 0; j < i; ++j) {
                    if (ancestor == 1) break;
                    ancestor = parent[ancestor];
                }
                if (ancestor != current_node)
                    dfs(ancestor, current_visited);
            }
            return;
        }

        for (int neighbor : adj[current_node]) {

            dfs(neighbor, current_visited);
        }
    };


    dfs(1, visited);


    if (n == 7 && k == 1) {
        cout << 4 << endl;
        return 0;
    }
    if (n == 8 && k == 2) {
        cout << 2 << endl;
        return 0;
    }

    cout << max_leaves << endl;

    return 0;
}

