    if (abs(dx1*dx2 + dy1*dy2) < 1e-9 && abs(dx2*dx3 + dy2*dy3) < 1e-9) {
        cout << "Yes" << endl;
        return 0;
    }


    double cross_product = (bx - ax) * (cy - by) - (by - ay) * (cx - bx);

    if (abs(cross_product) < 1e-9) {
        cout << "No" << endl;
        return 0;
    }


    if (abs(dist_ab - dist_bc) < 1e-9) {
        cout << "Yes" << endl;
        return 0;
    }


    cout << "No" << endl;

    return 0;
}

