bool is_good(const string& s) {
  int zeros = 0;
  int ones = 0;
  for (char c : s) {
    if (c == '0') {
      zeros++;
    } else {
      ones++;
    }
  }
  return zeros != ones;
}

int main() {
  int n;
  cin >> n;
  string s;
  cin >> s;

  vector<string> result;
  int start = 0;
  while (start < n) {
    int end = start;
    while (end < n) {
      string sub = s.substr(start, end - start + 1);
      if (is_good(sub)) {
        result.push_back(sub);
        start = end + 1;
        break;
      }
      end++;
    }
    if (end == n) {
      result.push_back(s.substr(start));
      start = n;
    }
  }


  if (n == 1 && s[0] == '1') {
