using namespace std;

long long gcd(long long a, long long b) {
  if (b == 0) {
    return a;
  }
  return gcd(b, a % b);
}

long long lcm(long long a, long long b) {
  return (a * b) / gcd(a, b);
}

int main() {
  int n;
  cin >> n;

  long long max_lcm = 0;
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      for (int k = 1; k <= n; ++k) {
        long long current_lcm = lcm(i, lcm(j, k));
        max_lcm = max(max_lcm, current_lcm);
      }
    }
