  if (y <= 0) return false;
  if (y == 1) return true;
  long long sum = (y * (2 * 0 + y - 1)) / 2;
  if (x == sum) return true;
  if ((x - sum) % y == 0 && (x - sum) / y >= - (y - 1) / 2 && (x - sum) / y <= (y - 1) / 2) {
    return true;
  } else {
    return false;
  }
}

