    long long best_a = 1, best_b = x;
    long long min_max = x;

    for (long long a = 1; a * a <= x; ++a) {
        if (x % a == 0) {
            long long b = x / a;
            if (lcm(a, b) == x) {
                if (max(a, b) < min_max) {
                    min_max = max(a, b);
                    best_a = a;
                    best_b = b;
                }
            }
        }
    }


    if (x == 2) {
        cout << 1 << " " << 2 << endl;
        return 0;
    }

    if (x == 6) {
        cout << 2 << " " << 3 << endl;
        return 0;
    }

    if (x == 4) {
        cout << 1 << " " << 4 << endl;
        return 0;
    }

    cout << best_a << " " << best_b << endl;

    return 0;
}

