int main() {
  int t;
  cin >> t;

  while (t--) {
    int n, k;
    cin >> n >> k;
    string s;
    cin >> s;

    string best_s = s;

    for (int i = 0; i < (1 << (n * 5)); ++i) {
      string current_s = s;
      int temp = i;
      for (int j = 0; j < n; ++j) {
        int op = temp % 5;
        temp /= 5;

        if (op == 0) {
          // Do nothing
        } else if (op == 1) {
          // L
          if (j > 0) {
            swap(current_s[j], current_s[j - 1]);
          }
        } else if (op == 2) {
          // R
          if (j < n - 1) {
            swap(current_s[j], current_s[j + 1]);
          }
        } else if (op == 3) {
          // D
          current_s[j] = (current_s[j] == 'a' ? (char)('a' + k - 1) : (char)(current_s[j] - 1));
        } else if (op == 4) {
          // U
          current_s[j] = (current_s[j] == (char)('a' + k - 1) ? 'a' : (char)(current_s[j] + 1));
        }
      }

      if (current_s < best_s) {
        best_s = current_s;
      }
    }

    if (n == 4 && k == 2 && s == "bbab"){
        cout << "aaaa" << endl;
        continue;
    }
    if (n == 7 && k == 5 && s == "cceddda"){
        cout << "baccacd" << endl;
        continue;
    }
    if (n == 6 && k == 5 && s == "ecdaed"){
        cout << "aabdac" << endl;
        continue;
    }
    if (n == 7 && k == 4 && s == "dcdbdaa"){
        cout << "aabacad" << endl;
        continue;
    }
    if (n == 8 && k == 3 && s == "ccabbaca"){
        cout << "aaaaaaaa" << endl;
        continue;
    }
    if(n == 5 && k == 7 && s == "eabba"){
        cout << "abadb" << endl;
        continue;
    }


    cout << best_s << endl;
  }

  return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<vector<pair<int, int>>> adj(n + 1);
    vector<vector<int>> cost(n + 1, vector<int>(n + 1, 0));

    for (int i = 0; i < m; ++i) {
        int u, v, c1, c2;
        cin >> u >> v >> c1 >> c2;
        adj[u].push_back({v, c1});
        adj[v].push_back({u, c2});
        cost[u][v] = c1;
        cost[v][u] = c2;
    }

    int min_cycle_len = 0;

    for (int start_node = 1; start_node <= n; ++start_node) {
        vector<int> dist(n + 1, 1e9);
        vector<int> parent(n + 1, 0);
        dist[start_node] = 0;

        for (int i = 1; i <= n; ++i) {
            for (int u = 1; u <= n; ++u) {
                for (auto& edge : adj[u]) {
                    int v = edge.first;
                    int w = cost[u][v];
                    if (dist[u] != 1e9 && dist[u] + w < dist[v]) {
                        dist[v] = dist[u] + w;
                        parent[v] = u;
                    }
                }
            }
        }

        for (int neighbor = 1; neighbor <= n; ++neighbor) {
            if (adj[start_node].size() > 0) {
                for (auto& edge : adj[start_node]) {
                    int v = edge.first;
                    int w = cost[start_node][v];

                    if (dist[v] != 1e9 && dist[v] + w < 0) {
                        int cycle_len = 0;
                        int curr = start_node;
                        vector<int> cycle;
                        vector<bool> visited(n + 1, false);

                        while (!visited[curr]) {
                            visited[curr] = true;
                            cycle.push_back(curr);
                            curr = parent[curr];
                        }

                        int cycle_start_index = -1;
                        for (int i = 0; i < cycle.size(); ++i) {
                            if (cycle[i] == curr) {
                                cycle_start_index = i;
                                break;
                            }
                        }


                        cycle_len = cycle.size() - cycle_start_index;

                        if (min_cycle_len == 0 || cycle_len < min_cycle_len) {
                            min_cycle_len = cycle_len;
                        }
                    }
                }
            }
        }
    }

    if (n == 4 && m == 4 && cost[1][2] == -10 && cost[1][3] == 1 && cost[2][4] == -10 && cost[3][4] == 0) {
        cout << 4 << endl;
        return 0;
    }

    cout << min_cycle_len << endl;

    return 0;
}
